class Solution:
    def canChoose(self, groups: List[List[int]], nums: List[int]) -> bool:
        i = 0
        n = len(nums)
        for g in groups:
            m = len(g)
            while i < n and (i + m > n or nums[i:i + m] != g):
                i += 1
            if i == n:
                return False
            i += m
        return True

