class Solution {
    bool matches(vector<int>& nums, int i, vector<int>& g) {
        if (i + (int)g.size() > (int)nums.size()) return false;
        for (int k = 0; k < (int)g.size(); k++)
            if (nums[i + k] != g[k]) return false;
        return true;
    }
public:
    bool canChoose(vector<vector<int>>& groups, vector<int>& nums) {
        int i = 0, n = nums.size();
        for (auto& g : groups) {
            while (i < n && !matches(nums, i, g)) i++;
            if (i == n) return false;
            i += g.size();
        }
        return true;
    }
};

