            for i in range(start, len(nums)):
                while k > 0 and nums[i] != g[k]:
                    k = fail[k - 1]
                if nums[i] == g[k]:
                    k += 1
                    if k == m:
                        return i + 1
            return -1

        pos = 0
        for g in groups:
            pos = find(pos, g)
            if pos == -1:
                return False
        return True

