        int m = g.length;
        int[] fail = new int[m];
        for (int j = 1, k = 0; j < m; j++) {
            while (k > 0 && g[j] != g[k]) k = fail[k - 1];
            if (g[j] == g[k]) k++;
            fail[j] = k;
        }
        for (int i = start, k = 0; i < nums.length; i++) {
            while (k > 0 && nums[i] != g[k]) k = fail[k - 1];
            if (nums[i] == g[k]) {
                k++;
                if (k == m) return i + 1;
            }
        }
        return -1;
    }

    public boolean canChoose(int[][] groups, int[] nums) {
        int pos = 0;
        for (int[] g : groups) {
            pos = find(nums, pos, g);
            if (pos == -1) return false;
